/**
 * Israel deep dive: the hand-written cards for /countries/il/. Plain English first, detail second, every card
 * with its sources. Entity lists (institutions, companies, drugs, trials, papers, people) are pulled from the
 * graph on the page by id so they stay in step with the corpus. Figures are quoted only where the linked source
 * states them, with the cohort and the year.
 *
 * Sourcing note, because it shapes what this page can and cannot say: www.gov.il serves a Cloudflare challenge to
 * automated clients, so Ministry of Health HTML pages could not be read; Ministry PDFs on gov.il/BlobFolder are
 * readable and were downloaded and text-extracted, which is how the National Cancer Registry's own reports are
 * quoted here. So were the statute (he.wikisource), the State Comptroller's May 2022 report, National Insurance
 * Institute publications, Knesset Research and Information Center papers, the health funds' own co-payment
 * schedules, and the peer-reviewed literature through Europe PMC. Every load-bearing number below was re-checked
 * against the primary document by the author of this file, not taken as prose from a summary. Where a source
 * contradicts itself or two sources disagree, both are given.
 */
export type CountryCard = { id: string; title: string; plain: string; detail: string; links: Array<{ label: string; url: string }> };

